    CopyDBClusterParameterGroupMessage.add_member(:source_db_cluster_parameter_group_identifier, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'SourceDBClusterParameterGroupIdentifier', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>The identifier or Amazon Resource Name (ARN) for the source cluster parameter group.</p>\n         <p>Constraints:</p>\n         <ul>\n            <li>\n               <p>Must specify a valid cluster parameter group.</p>\n            </li>\n            <li>\n               <p>If the source cluster parameter group is in the same Amazon Web Services Region as the copy, specify a valid parameter group identifier; for example, <code>my-db-cluster-param-group</code>, or a valid ARN.</p>\n            </li>\n            <li>\n               <p>If the source parameter group is in a different Amazon Web Services Region than the copy, specify a valid cluster parameter group ARN; for example, <code>arn:aws:rds:us-east-1:123456789012:sample-cluster:sample-parameter-group</code>.</p>\n            </li>\n         </ul>", "smithy.api#required" => {}}))
    CopyDBClusterParameterGroupMessage.add_member(:target_db_cluster_parameter_group_identifier, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'TargetDBClusterParameterGroupIdentifier', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>The identifier for the copied cluster parameter group.</p>\n         <p>Constraints:</p>\n         <ul>\n            <li>\n               <p>Cannot be null, empty, or blank.</p>\n            </li>\n            <li>\n               <p>Must contain from 1 to 255 letters, numbers, or hyphens.\n                    </p>\n            </li>\n            <li>\n               <p>The first character must be a letter.</p>\n            </li>\n            <li>\n               <p>Cannot end with a hyphen or contain two consecutive hyphens.\n                    </p>\n            </li>\n         </ul>\n         <p>Example: <code>my-cluster-param-group1</code>\n         </p>", "smithy.api#required" => {}}))
    CopyDBClusterParameterGroupMessage.add_member(:target_db_cluster_parameter_group_description, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'TargetDBClusterParameterGroupDescription', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>A description for the copied cluster parameter group.</p>", "smithy.api#required" => {}}))
    CopyDBClusterParameterGroupMessage.add_member(:tags, Smithy::Schema::Shapes::ShapeRef.new(shape: TagList, location_name: 'Tags', traits: {"smithy.api#documentation" => "<p>The tags that are to be assigned to the parameter group.</p>"}))
