    CreateDBClusterMessage.add_member(:availability_zones, Smithy::Schema::Shapes::ShapeRef.new(shape: AvailabilityZones, location_name: 'AvailabilityZones', traits: {"smithy.api#documentation" => "<p>A list of Amazon EC2 Availability Zones that instances in the\n            cluster can be created in.</p>"}))
    CreateDBClusterMessage.add_member(:backup_retention_period, Smithy::Schema::Shapes::ShapeRef.new(shape: IntegerOptional, location_name: 'BackupRetentionPeriod', traits: {"smithy.api#documentation" => "<p>The number of days for which automated backups are retained. You\n            must specify a minimum value of 1.</p>\n         <p>Default: 1</p>\n         <p>Constraints:</p>\n         <ul>\n            <li>\n               <p>Must be a value from 1 to 35.</p>\n            </li>\n         </ul>"}))
    CreateDBClusterMessage.add_member(:db_cluster_identifier, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'DBClusterIdentifier', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>The cluster identifier. This parameter is stored as a lowercase\n            string.</p>\n         <p>Constraints:</p>\n         <ul>\n            <li>\n               <p>Must contain from 1 to 63 letters, numbers, or hyphens.\n                    </p>\n            </li>\n            <li>\n               <p>The first character must be a letter.</p>\n            </li>\n            <li>\n               <p>Cannot end with a hyphen or contain two consecutive hyphens.\n                    </p>\n            </li>\n         </ul>\n         <p>Example: <code>my-cluster</code>\n         </p>", "smithy.api#required" => {}}))
    CreateDBClusterMessage.add_member(:db_cluster_parameter_group_name, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'DBClusterParameterGroupName', traits: {"smithy.api#documentation" => "<p>The name of the cluster parameter group to associate with this\n            cluster.</p>"}))
    CreateDBClusterMessage.add_member(:vpc_security_group_ids, Smithy::Schema::Shapes::ShapeRef.new(shape: VpcSecurityGroupIdList, location_name: 'VpcSecurityGroupIds', traits: {"smithy.api#documentation" => "<p>A list of EC2 VPC security groups to associate with this cluster.\n            </p>"}))
    CreateDBClusterMessage.add_member(:db_subnet_group_name, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'DBSubnetGroupName', traits: {"smithy.api#documentation" => "<p>A subnet group to associate with this cluster.</p>\n         <p>Constraints: Must match the name of an existing\n            <code>DBSubnetGroup</code>. Must not be default.</p>\n         <p>Example: <code>mySubnetgroup</code>\n         </p>"}))
    CreateDBClusterMessage.add_member(:engine, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'Engine', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>The name of the database engine to be used for this cluster.</p>\n         <p>Valid values: <code>docdb</code>\n         </p>", "smithy.api#required" => {}}))
    CreateDBClusterMessage.add_member(:engine_version, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'EngineVersion', traits: {"smithy.api#documentation" => "<p>The version number of the database engine to use. The <code>--engine-version</code> will default to the latest major engine version. For production workloads, we recommend explicitly declaring this parameter with the intended major engine version.</p>"}))
    CreateDBClusterMessage.add_member(:port, Smithy::Schema::Shapes::ShapeRef.new(shape: IntegerOptional, location_name: 'Port', traits: {"smithy.api#documentation" => "<p>The port number on which the instances in the cluster accept\n            connections.</p>"}))
    CreateDBClusterMessage.add_member(:master_username, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'MasterUsername', traits: {"smithy.api#documentation" => "<p>The name of the master user for the cluster.</p>\n         <p>Constraints:</p>\n         <ul>\n            <li>\n               <p>Must be from 1 to 63 letters or numbers.</p>\n            </li>\n            <li>\n               <p>The first character must be a letter.</p>\n            </li>\n            <li>\n               <p>Cannot be a reserved word for the chosen database engine.\n                    </p>\n            </li>\n         </ul>"}))
    CreateDBClusterMessage.add_member(:master_user_password, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'MasterUserPassword', traits: {"smithy.api#documentation" => "<p>The password for the master database user. This password can\n            contain any printable ASCII character except forward slash (/),\n            double quote (\"), or the \"at\" symbol (@).</p>\n         <p>Constraints: Must contain from 8 to 100 characters.</p>"}))
    CreateDBClusterMessage.add_member(:preferred_backup_window, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'PreferredBackupWindow', traits: {"smithy.api#documentation" => "<p>The daily time range during which automated backups are created if\n            automated backups are enabled using the <code>BackupRetentionPeriod</code> parameter. </p>\n         <p>The default is a 30-minute window selected at random from an 8-hour block of time for each Amazon Web Services Region. </p>\n         <p>Constraints:</p>\n         <ul>\n            <li>\n               <p>Must be in the format <code>hh24:mi-hh24:mi</code>.</p>\n            </li>\n            <li>\n               <p>Must be in Universal Coordinated Time (UTC).</p>\n            </li>\n            <li>\n               <p>Must not conflict with the preferred maintenance window.\n                    </p>\n            </li>\n            <li>\n               <p>Must be at least 30 minutes.</p>\n            </li>\n         </ul>"}))
    CreateDBClusterMessage.add_member(:preferred_maintenance_window, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'PreferredMaintenanceWindow', traits: {"smithy.api#documentation" => "<p>The weekly time range during which system maintenance can occur,\n            in Universal Coordinated Time (UTC).</p>\n         <p>Format: <code>ddd:hh24:mi-ddd:hh24:mi</code>\n         </p>\n         <p>The default is a 30-minute window selected at random from an 8-hour block of time for each Amazon Web Services Region, occurring on a random day of the week.</p>\n         <p>Valid days: Mon, Tue, Wed, Thu, Fri, Sat, Sun</p>\n         <p>Constraints: Minimum 30-minute window.</p>"}))
    CreateDBClusterMessage.add_member(:tags, Smithy::Schema::Shapes::ShapeRef.new(shape: TagList, location_name: 'Tags', traits: {"smithy.api#documentation" => "<p>The tags to be assigned to the cluster.</p>"}))
    CreateDBClusterMessage.add_member(:storage_encrypted, Smithy::Schema::Shapes::ShapeRef.new(shape: BooleanOptional, location_name: 'StorageEncrypted', traits: {"smithy.api#documentation" => "<p>Specifies whether the cluster is encrypted.</p>"}))
    CreateDBClusterMessage.add_member(:kms_key_id, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'KmsKeyId', traits: {"smithy.api#documentation" => "<p>The KMS key identifier for an encrypted cluster.</p>\n         <p>The KMS key identifier is the Amazon Resource Name (ARN) for the KMS encryption key. If you are creating a cluster using the same Amazon Web Services account that owns the KMS encryption key that is used to encrypt the new cluster, you can use the KMS key alias instead of the ARN for the KMS encryption key.</p>\n         <p>If an encryption key is not specified in <code>KmsKeyId</code>:\n            </p>\n         <ul>\n            <li>\n               <p>If the <code>StorageEncrypted</code> parameter is\n                    <code>true</code>, Amazon DocumentDB uses your default encryption key.\n                    </p>\n            </li>\n         </ul>\n         <p>KMS creates the default encryption key for your Amazon Web Services account. Your Amazon Web Services account has a different default encryption key for each Amazon Web Services Regions.</p>"}))
    CreateDBClusterMessage.add_member(:pre_signed_url, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'PreSignedUrl', traits: {"smithy.api#documentation" => "<p>Not currently supported.\n            </p>"}))
    CreateDBClusterMessage.add_member(:enable_cloudwatch_logs_exports, Smithy::Schema::Shapes::ShapeRef.new(shape: LogTypeList, location_name: 'EnableCloudwatchLogsExports', traits: {"smithy.api#documentation" => "<p>A list of log types that need to be enabled for exporting to Amazon\n            CloudWatch Logs. You can enable audit logs or profiler logs. For more\n            information, see <a href=\"https://docs.aws.amazon.com/documentdb/latest/developerguide/event-auditing.html\">\n                Auditing Amazon DocumentDB Events</a>\n            and <a href=\"https://docs.aws.amazon.com/documentdb/latest/developerguide/profiling.html\">\n                Profiling Amazon DocumentDB Operations</a>.\n        </p>"}))
    CreateDBClusterMessage.add_member(:deletion_protection, Smithy::Schema::Shapes::ShapeRef.new(shape: BooleanOptional, location_name: 'DeletionProtection', traits: {"smithy.api#documentation" => "<p>Specifies whether this cluster can be deleted. If\n            <code>DeletionProtection</code> is enabled, the cluster cannot be\n            deleted unless it is modified and <code>DeletionProtection</code> is\n            disabled. <code>DeletionProtection</code> protects clusters from\n            being accidentally deleted.</p>"}))
