    CreateEventSubscriptionMessage.add_member(:source_ids, Smithy::Schema::Shapes::ShapeRef.new(shape: SourceIdsList, location_name: 'SourceIds', traits: {"smithy.api#documentation" => "<p>The list of identifiers of the event sources for which events are returned. If not specified, then all sources are included in the response. An identifier must begin with a letter and must contain only ASCII letters, digits, and hyphens; it can't end with a\n            hyphen or contain two consecutive hyphens.</p>\n         <p>Constraints:</p>\n         <ul>\n            <li>\n               <p>If <code>SourceIds</code> are provided, <code>SourceType</code> must also be\n                    provided.</p>\n            </li>\n            <li>\n               <p>If the source type is an instance, a <code>DBInstanceIdentifier</code> must\n                    be provided.</p>\n            </li>\n            <li>\n               <p>If the source type is a security group, a <code>DBSecurityGroupName</code>\n                    must be provided.</p>\n            </li>\n            <li>\n               <p>If the source type is a parameter group, a\n                        <code>DBParameterGroupName</code> must be provided.</p>\n            </li>\n            <li>\n               <p>If the source type is a snapshot, a <code>DBSnapshotIdentifier</code> must\n                    be provided.</p>\n            </li>\n         </ul>"}))
