    ModifyDBClusterMessage.add_member(:db_cluster_parameter_group_name, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'DBClusterParameterGroupName', traits: {"smithy.api#documentation" => "<p>The name of the cluster parameter group to use for the cluster.</p>"}))
