    ModifyDBClusterMessage.add_member(:port, Smithy::Schema::Shapes::ShapeRef.new(shape: IntegerOptional, location_name: 'Port', traits: {"smithy.api#documentation" => "<p>The port number on which the cluster accepts connections.</p>\n         <p>Constraints: Must be a value from <code>1150</code> to <code>65535</code>. </p>\n         <p>Default: The same port as the original cluster.</p>"}))
    ModifyDBClusterMessage.add_member(:master_user_password, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'MasterUserPassword', traits: {"smithy.api#documentation" => "<p>The password for the master database user. This password can contain any printable\n            ASCII character except forward slash (/), double quote (\"), or the \"at\" symbol\n            (@).</p>\n         <p>Constraints: Must contain from 8 to 100 characters.</p>"}))
    ModifyDBClusterMessage.add_member(:preferred_backup_window, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'PreferredBackupWindow', traits: {"smithy.api#documentation" => "<p>The daily time range during which automated backups are created if automated backups\n            are enabled, using the <code>BackupRetentionPeriod</code> parameter. </p>\n         <p>The default is a 30-minute window selected at random from an 8-hour block of time for\n            each Amazon Web Services Region. </p>\n         <p>Constraints:</p>\n         <ul>\n            <li>\n               <p>Must be in the format <code>hh24:mi-hh24:mi</code>.</p>\n            </li>\n            <li>\n               <p>Must be in Universal Coordinated Time (UTC).</p>\n            </li>\n            <li>\n               <p>Must not conflict with the preferred maintenance window.</p>\n            </li>\n            <li>\n               <p>Must be at least 30 minutes.</p>\n            </li>\n         </ul>"}))
    ModifyDBClusterMessage.add_member(:preferred_maintenance_window, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'PreferredMaintenanceWindow', traits: {"smithy.api#documentation" => "<p>The weekly time range during which system maintenance can occur, in Universal\n            Coordinated Time (UTC).</p>\n         <p>Format: <code>ddd:hh24:mi-ddd:hh24:mi</code>\n         </p>\n         <p>The default is a 30-minute window selected at random from an 8-hour block of time for\n            each Amazon Web Services Region, occurring on a random day of the week. </p>\n         <p>Valid days: Mon, Tue, Wed, Thu, Fri, Sat, Sun</p>\n         <p>Constraints: Minimum 30-minute window.</p>"}))
    ModifyDBClusterMessage.add_member(:cloudwatch_logs_export_configuration, Smithy::Schema::Shapes::ShapeRef.new(shape: CloudwatchLogsExportConfiguration, location_name: 'CloudwatchLogsExportConfiguration', traits: {"smithy.api#documentation" => "<p>The configuration setting for the log types to be enabled for export to Amazon\n            CloudWatch Logs for a specific instance or cluster. The\n                <code>EnableLogTypes</code> and <code>DisableLogTypes</code> arrays determine which\n            logs are exported (or not exported) to CloudWatch Logs.</p>"}))
    ModifyDBClusterMessage.add_member(:engine_version, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'EngineVersion', traits: {"smithy.api#documentation" => "<p>The version number of the database engine to which you want to upgrade.\n             Changing this parameter results in an outage. The change is applied during\n             the next maintenance window unless <code>ApplyImmediately</code> is enabled.</p>\n         <p>To list all of the available engine versions for Amazon DocumentDB use the following command:</p>\n         <p>\n            <code>aws docdb describe-db-engine-versions --engine docdb --query \"DBEngineVersions[].EngineVersion\"</code>\n         </p>"}))
    ModifyDBClusterMessage.add_member(:allow_major_version_upgrade, Smithy::Schema::Shapes::ShapeRef.new(shape: Boolean, location_name: 'AllowMajorVersionUpgrade', traits: {"smithy.api#documentation" => "<p>A value that indicates whether major version upgrades are allowed.</p>\n         <p>Constraints: You must allow major version upgrades when specifying a value for the\n             <code>EngineVersion</code> parameter that is a different major version than the DB\n             cluster's current version.</p>"}))
    ModifyDBClusterMessage.add_member(:deletion_protection, Smithy::Schema::Shapes::ShapeRef.new(shape: BooleanOptional, location_name: 'DeletionProtection', traits: {"smithy.api#documentation" => "<p>Specifies whether this cluster can be deleted. If <code>DeletionProtection</code> is\n            enabled, the cluster cannot be deleted unless it is modified and\n                <code>DeletionProtection</code> is disabled. <code>DeletionProtection</code>\n            protects clusters from being accidentally deleted.</p>"}))
    ModifyDBClusterMessage.add_member(:storage_type, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'StorageType', traits: {"smithy.api#documentation" => "<p>The storage type to associate with the DB cluster.</p>\n         <p>For information on storage types for Amazon DocumentDB clusters, see \n            Cluster storage configurations in the <i>Amazon DocumentDB Developer Guide</i>.</p>\n         <p>Valid values for storage type - <code>standard | iopt1</code>\n         </p>\n         <p>Default value is <code>standard </code>\n         </p>"}))
    ModifyDBClusterMessage.add_member(:serverless_v2_scaling_configuration, Smithy::Schema::Shapes::ShapeRef.new(shape: ServerlessV2ScalingConfiguration, location_name: 'ServerlessV2ScalingConfiguration', traits: {"smithy.api#documentation" => "<p>Contains the scaling configuration of an Amazon DocumentDB Serverless cluster.</p>"}))
    ModifyDBClusterMessage.add_member(:manage_master_user_password, Smithy::Schema::Shapes::ShapeRef.new(shape: BooleanOptional, location_name: 'ManageMasterUserPassword', traits: {"smithy.api#documentation" => "<p>Specifies whether to manage the master user password with Amazon Web Services Secrets Manager.\n            If the cluster doesn't manage the master user password with Amazon Web Services Secrets Manager, you can turn on this management. \n            In this case, you can't specify <code>MasterUserPassword</code>.\n            If the cluster already manages the master user password with Amazon Web Services Secrets Manager, and you specify that the master user password is not managed with Amazon Web Services Secrets Manager, then you must specify <code>MasterUserPassword</code>. \n            In this case, Amazon DocumentDB deletes the secret and uses the new password for the master user specified by <code>MasterUserPassword</code>.</p>"}))
    ModifyDBClusterMessage.add_member(:master_user_secret_kms_key_id, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'MasterUserSecretKmsKeyId', traits: {"smithy.api#documentation" => "<p>The Amazon Web Services KMS key identifier to encrypt a secret that is automatically generated and managed in Amazon Web Services Secrets Manager.</p>\n         <p>This setting is valid only if both of the following conditions are met:</p>\n         <ul>\n            <li>\n               <p>The cluster doesn't manage the master user password in Amazon Web Services Secrets Manager. \n                If the cluster already manages the master user password in Amazon Web Services Secrets Manager, you can't change the KMS key that is used to encrypt the secret.</p>\n            </li>\n            <li>\n               <p>You are enabling <code>ManageMasterUserPassword</code> to manage the master user password in Amazon Web Services Secrets Manager. \n                If you are turning on <code>ManageMasterUserPassword</code> and don't specify <code>MasterUserSecretKmsKeyId</code>, then the <code>aws/secretsmanager</code> KMS key is used to encrypt the secret. \n                If the secret is in a different Amazon Web Services account, then you can't use the <code>aws/secretsmanager</code> KMS key to encrypt the secret, and you must use a customer managed KMS key.</p>\n            </li>\n         </ul>\n         <p>The Amazon Web Services KMS key identifier is the key ARN, key ID, alias ARN, or alias name for the KMS key. \n            To use a KMS key in a different Amazon Web Services account, specify the key ARN or alias ARN.</p>\n         <p>There is a default KMS key for your Amazon Web Services account. \n            Your Amazon Web Services account has a different default KMS key for each Amazon Web Services Region.</p>"}))
    ModifyDBClusterMessage.add_member(:rotate_master_user_password, Smithy::Schema::Shapes::ShapeRef.new(shape: BooleanOptional, location_name: 'RotateMasterUserPassword', traits: {"smithy.api#documentation" => "<p>Specifies whether to rotate the secret managed by Amazon Web Services Secrets Manager for the master user password.</p>\n         <p>This setting is valid only if the master user password is managed by Amazon DocumentDB in Amazon Web Services Secrets Manager for the cluster. \n            The secret value contains the updated password.</p>\n         <p>Constraint: You must apply the change immediately when rotating the master user password.</p>"}))
    ModifyDBClusterMessage.type = Types::ModifyDBClusterMessage
    ModifyDBClusterParameterGroupMessage.add_member(:db_cluster_parameter_group_name, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'DBClusterParameterGroupName', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>The name of the cluster parameter group to modify.</p>", "smithy.api#required" => {}}))
