    ModifyDBClusterSnapshotAttributeMessage.add_member(:db_cluster_snapshot_identifier, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'DBClusterSnapshotIdentifier', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>The identifier for the cluster snapshot to modify the attributes for.</p>", "smithy.api#required" => {}}))
    ModifyDBClusterSnapshotAttributeMessage.add_member(:attribute_name, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'AttributeName', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>The name of the cluster snapshot attribute to modify.</p>\n         <p>To manage authorization for other Amazon Web Services accounts to copy or restore a manual cluster\n            snapshot, set this value to <code>restore</code>.</p>", "smithy.api#required" => {}}))
    ModifyDBClusterSnapshotAttributeMessage.add_member(:values_to_add, Smithy::Schema::Shapes::ShapeRef.new(shape: AttributeValueList, location_name: 'ValuesToAdd', traits: {"smithy.api#documentation" => "<p>A list of cluster snapshot attributes to add to the attribute specified by <code>AttributeName</code>.</p>\n         <p>To authorize other Amazon Web Services accounts to copy or restore a manual cluster snapshot, set this list to include one or more Amazon Web Services account IDs. To make the manual cluster snapshot restorable by any Amazon Web Services account, set it to <code>all</code>. Do not add the <code>all</code> value for any manual cluster snapshots that contain private information that you don't want to be available to all Amazon Web Services accounts.</p>"}))
    ModifyDBClusterSnapshotAttributeMessage.add_member(:values_to_remove, Smithy::Schema::Shapes::ShapeRef.new(shape: AttributeValueList, location_name: 'ValuesToRemove', traits: {"smithy.api#documentation" => "<p>A list of cluster snapshot attributes to remove from the attribute specified by <code>AttributeName</code>.</p>\n         <p>To remove authorization for other Amazon Web Services accounts to copy or restore a manual cluster snapshot, set this list to include one or more Amazon Web Services account identifiers. To remove authorization for any Amazon Web Services account to copy or restore the cluster snapshot, set it to <code>all</code> . If you specify <code>all</code>, an Amazon Web Services account whose account ID is explicitly added to the <code>restore</code> attribute can still copy or restore a manual cluster snapshot.</p>"}))
