    ModifyDBInstanceMessage.add_member(:db_instance_identifier, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'DBInstanceIdentifier', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>The instance identifier. This value is stored as a lowercase string.</p>\n         <p>Constraints:</p>\n         <ul>\n            <li>\n               <p>Must match the identifier of an existing <code>DBInstance</code>.</p>\n            </li>\n         </ul>", "smithy.api#required" => {}}))
    ModifyDBInstanceMessage.add_member(:db_instance_class, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'DBInstanceClass', traits: {"smithy.api#documentation" => "<p>The new compute and memory capacity of the instance; for example, <code>db.r5.large</code>. Not all instance classes are available in all Amazon Web Services Regions. </p>\n         <p>If you modify the instance class, an outage occurs during the change. The change is\n            applied during the next maintenance window, unless <code>ApplyImmediately</code> is\n            specified as <code>true</code> for this request. </p>\n         <p>Default: Uses existing setting.</p>"}))
    ModifyDBInstanceMessage.add_member(:apply_immediately, Smithy::Schema::Shapes::ShapeRef.new(shape: Boolean, location_name: 'ApplyImmediately', traits: {"smithy.api#documentation" => "<p>Specifies whether the modifications in this request and any pending modifications are\n            asynchronously applied as soon as possible, regardless of the\n                <code>PreferredMaintenanceWindow</code> setting for the instance. </p>\n         <p> If this parameter is set to <code>false</code>, changes to the instance are\n            applied during the next maintenance window. Some parameter changes can cause an outage\n            and are applied on the next reboot.</p>\n         <p>Default: <code>false</code>\n         </p>"}))
    ModifyDBInstanceMessage.add_member(:preferred_maintenance_window, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'PreferredMaintenanceWindow', traits: {"smithy.api#documentation" => "<p>The weekly time range (in UTC) during which system maintenance can occur, which might\n            result in an outage. Changing this parameter doesn't result in an outage except in the\n            following situation, and the change is asynchronously applied as soon as possible. If\n            there are pending actions that cause a reboot, and the maintenance window is changed to\n            include the current time, changing this parameter causes a reboot of the instance. If\n            you are moving this window to the current time, there must be at least 30 minutes\n            between the current time and end of the window to ensure that pending changes are\n            applied.</p>\n         <p>Default: Uses existing setting.</p>\n         <p>Format: <code>ddd:hh24:mi-ddd:hh24:mi</code>\n         </p>\n         <p>Valid days: Mon, Tue, Wed, Thu, Fri, Sat, Sun</p>\n         <p>Constraints: Must be at least 30 minutes.</p>"}))
    ModifyDBInstanceMessage.add_member(:auto_minor_version_upgrade, Smithy::Schema::Shapes::ShapeRef.new(shape: BooleanOptional, location_name: 'AutoMinorVersionUpgrade', traits: {"smithy.api#documentation" => "<p>This parameter does not apply to Amazon DocumentDB. Amazon DocumentDB does not perform minor version upgrades regardless of the value set.</p>"}))
    ModifyDBInstanceMessage.add_member(:new_db_instance_identifier, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'NewDBInstanceIdentifier', traits: {"smithy.api#documentation" => "<p> The new instance identifier for the instance when renaming an instance. When you change the instance identifier, an instance reboot occurs immediately if you set <code>Apply Immediately</code> to <code>true</code>. It occurs during the next maintenance window if you set <code>Apply Immediately</code> to <code>false</code>. This value is stored as a lowercase string. </p>\n         <p>Constraints:</p>\n         <ul>\n            <li>\n               <p>Must contain from 1 to 63 letters, numbers, or hyphens.</p>\n            </li>\n            <li>\n               <p>The first character must be a letter.</p>\n            </li>\n            <li>\n               <p>Cannot end with a hyphen or contain two consecutive hyphens.</p>\n            </li>\n         </ul>\n         <p>Example: <code>mydbinstance</code>\n         </p>"}))
    ModifyDBInstanceMessage.add_member(:ca_certificate_identifier, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'CACertificateIdentifier', traits: {"smithy.api#documentation" => "<p>Indicates the certificate that needs to be associated with the instance.</p>"}))
    ModifyDBInstanceMessage.add_member(:copy_tags_to_snapshot, Smithy::Schema::Shapes::ShapeRef.new(shape: BooleanOptional, location_name: 'CopyTagsToSnapshot', traits: {"smithy.api#documentation" => "<p>A value that indicates whether to copy all tags from the DB instance to snapshots of the DB instance. By default, tags are not copied.</p>"}))
    ModifyDBInstanceMessage.add_member(:promotion_tier, Smithy::Schema::Shapes::ShapeRef.new(shape: IntegerOptional, location_name: 'PromotionTier', traits: {"smithy.api#documentation" => "<p>A value that specifies the order in which an Amazon DocumentDB replica is promoted to the primary instance after a failure of the existing primary instance.</p>\n         <p>Default: 1</p>\n         <p>Valid values: 0-15</p>"}))
    ModifyDBInstanceMessage.add_member(:enable_performance_insights, Smithy::Schema::Shapes::ShapeRef.new(shape: BooleanOptional, location_name: 'EnablePerformanceInsights', traits: {"smithy.api#documentation" => "<p>A value that indicates whether to enable Performance Insights for the DB Instance. For\n            more information, see <a href=\"https://docs.aws.amazon.com/documentdb/latest/developerguide/performance-insights.html\">Using Amazon\n                Performance Insights</a>.</p>"}))
    ModifyDBInstanceMessage.add_member(:performance_insights_kms_key_id, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'PerformanceInsightsKMSKeyId', traits: {"smithy.api#documentation" => "<p>The KMS key identifier for encryption of Performance Insights\n            data.</p>\n         <p>The KMS key identifier is the key ARN, key ID, alias ARN, or alias name\n            for the KMS key.</p>\n         <p>If you do not specify a value for PerformanceInsightsKMSKeyId, then Amazon DocumentDB uses your\n            default KMS key. There is a default KMS key for your\n            Amazon Web Services account. Your Amazon Web Services account has a different\n            default KMS key for each Amazon Web Services region.</p>"}))
    ModifyDBInstanceMessage.add_member(:certificate_rotation_restart, Smithy::Schema::Shapes::ShapeRef.new(shape: BooleanOptional, location_name: 'CertificateRotationRestart', traits: {"smithy.api#documentation" => "<p>Specifies whether the DB instance is restarted when you rotate your \n            SSL/TLS certificate.</p>\n         <p>By default, the DB instance is restarted when you rotate your SSL/TLS certificate. The certificate \n            is not updated until the DB instance is restarted.</p>\n         <important>\n            <p>Set this parameter only if you are <i>not</i> using SSL/TLS to connect to the DB instance.</p>\n         </important>\n         <p>If you are using SSL/TLS to connect to the DB instance, see <a href=\"https://docs.aws.amazon.com/documentdb/latest/developerguide/ca_cert_rotation.html\">Updating Your Amazon DocumentDB TLS \n            Certificates</a> and \n            <a href=\"https://docs.aws.amazon.com/documentdb/latest/developerguide/security.encryption.ssl.html\">\n                Encrypting Data in Transit</a> in the <i>Amazon DocumentDB Developer \n                    Guide</i>.</p>"}))
