    ModifyEventSubscriptionMessage.add_member(:subscription_name, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'SubscriptionName', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>The name of the Amazon DocumentDB event notification subscription.</p>", "smithy.api#required" => {}}))
    ModifyEventSubscriptionMessage.add_member(:sns_topic_arn, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'SnsTopicArn', traits: {"smithy.api#documentation" => "<p>The Amazon Resource Name (ARN) of the SNS topic created for event notification. The\n            ARN is created by Amazon SNS when you create a topic and subscribe to it.</p>"}))
    ModifyEventSubscriptionMessage.add_member(:source_type, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'SourceType', traits: {"smithy.api#documentation" => "<p>The type of source that is generating the events. For example, if you want to be notified of events generated by an instance, set this parameter to <code>db-instance</code>. If this value is not specified, all events are returned.</p>\n         <p>Valid values: <code>db-instance</code>, <code>db-parameter-group</code>, <code>db-security-group</code>\n         </p>"}))
    ModifyEventSubscriptionMessage.add_member(:event_categories, Smithy::Schema::Shapes::ShapeRef.new(shape: EventCategoriesList, location_name: 'EventCategories', traits: {"smithy.api#documentation" => "<p> A list of event categories for a <code>SourceType</code> that you want to subscribe\n            to.</p>"}))
    ModifyEventSubscriptionMessage.add_member(:enabled, Smithy::Schema::Shapes::ShapeRef.new(shape: BooleanOptional, location_name: 'Enabled', traits: {"smithy.api#documentation" => "<p> A Boolean value; set to <code>true</code> to activate the subscription. </p>"}))
