    RestoreDBClusterToPointInTimeMessage.add_member(:restore_type, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'RestoreType', traits: {"smithy.api#documentation" => "<p>The type of restore to be performed. You can specify one of the following values:</p>\n         <ul>\n            <li>\n               <p>\n                  <code>full-copy</code> - The new DB cluster is restored as a full copy of the\n                source DB cluster.</p>\n            </li>\n            <li>\n               <p>\n                  <code>copy-on-write</code> - The new DB cluster is restored as a clone of the\n                source DB cluster.</p>\n            </li>\n         </ul>\n         <p>Constraints: You can't specify <code>copy-on-write</code> if the engine version of the source DB cluster is earlier than 1.11.</p>\n         <p>If you don't specify a <code>RestoreType</code> value, then the new DB cluster is\n            restored as a full copy of the source DB cluster.</p>"}))
    RestoreDBClusterToPointInTimeMessage.add_member(:source_db_cluster_identifier, Smithy::Schema::Shapes::ShapeRef.new(shape: String, location_name: 'SourceDBClusterIdentifier', traits: {"smithy.api#clientOptional" => {}, "smithy.api#documentation" => "<p>The identifier of the source cluster from which to restore.</p>\n         <p>Constraints:</p>\n         <ul>\n            <li>\n               <p>Must match the identifier of an existing <code>DBCluster</code>.</p>\n            </li>\n         </ul>", "smithy.api#required" => {}}))
    RestoreDBClusterToPointInTimeMessage.add_member(:restore_to_time, Smithy::Schema::Shapes::ShapeRef.new(shape: TStamp, location_name: 'RestoreToTime', traits: {"smithy.api#documentation" => "<p>The date and time to restore the cluster to.</p>\n         <p>Valid values: A time in Universal Coordinated Time (UTC) format.</p>\n         <p>Constraints:</p>\n         <ul>\n            <li>\n               <p>Must be before the latest restorable time for the instance.</p>\n            </li>\n            <li>\n               <p>Must be specified if the <code>UseLatestRestorableTime</code> parameter is not provided.</p>\n            </li>\n            <li>\n               <p>Cannot be specified if the <code>UseLatestRestorableTime</code> parameter is <code>true</code>.</p>\n            </li>\n            <li>\n               <p>Cannot be specified if the <code>RestoreType</code> parameter is <code>copy-on-write</code>.</p>\n            </li>\n         </ul>\n         <p>Example: <code>2015-03-07T23:45:00Z</code>\n         </p>"}))
    RestoreDBClusterToPointInTimeMessage.add_member(:use_latest_restorable_time, Smithy::Schema::Shapes::ShapeRef.new(shape: Boolean, location_name: 'UseLatestRestorableTime', traits: {"smithy.api#documentation" => "<p>A value that is set to <code>true</code> to restore the cluster to the latest\n            restorable backup time, and <code>false</code> otherwise. </p>\n         <p>Default: <code>false</code>\n         </p>\n         <p>Constraints: Cannot be specified if the <code>RestoreToTime</code> parameter is\n            provided.</p>"}))
